const ELEMENT_PROP_KEYS = new Set(["theme","text","hold","stagger","accent","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  text: "Read it both ways.",
  hold: 16,
  stagger: 5,
  accent: "#E03C31",
  fontFamily: "Zen Kaku Gothic New",
  scale: 1,
  delay: 0,
  speed: 1,
};

type TategakiTurnElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof TategakiTurnBase>;

const TategakiTurnInner = forwardRef<
  HTMLDivElement,
  TategakiTurnElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<TategakiTurn>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <TategakiTurnBase
          {...(componentProps as unknown as ComponentProps<typeof TategakiTurnBase>)}
        />
      </div>
    </Sequence>
  );
});

export const TategakiTurn = Interactive.withSchema({
  Component: TategakiTurnInner,
  componentName: "<TategakiTurn>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
